CREATE TABLE user_account (
 id BINARY(16) NOT NULL, username VARCHAR(64), phone VARCHAR(32), email VARCHAR(320), password_hash VARCHAR(255) NOT NULL,
 role VARCHAR(16) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', failed_login_count INT NOT NULL DEFAULT 0,
 locked_until DATETIME(6), last_login_at DATETIME(6), deleted_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 PRIMARY KEY(id), UNIQUE KEY uk_user_username(username), UNIQUE KEY uk_user_phone(phone), UNIQUE KEY uk_user_email(email), KEY ix_user_status(status,deleted_at),
 CONSTRAINT ck_user_login CHECK(username IS NOT NULL OR phone IS NOT NULL OR email IS NOT NULL), CONSTRAINT ck_user_role CHECK(role IN('USER','ADMIN')), CONSTRAINT ck_user_status CHECK(status IN('ACTIVE','LOCKED','DISABLED','DELETED')), CONSTRAINT ck_user_failed CHECK(failed_login_count>=0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE user_session (
 id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, refresh_token_hash BINARY(32) NOT NULL, issued_at DATETIME(6) NOT NULL, expires_at DATETIME(6) NOT NULL, revoked_at DATETIME(6), last_seen_at DATETIME(6), client_metadata_json JSON, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 PRIMARY KEY(id), UNIQUE KEY uk_session_token(refresh_token_hash), KEY ix_session_user_expiry(user_id,expires_at), KEY ix_session_revoked(revoked_at), CONSTRAINT ck_session_expiry CHECK(expires_at>issued_at), CONSTRAINT fk_session_user FOREIGN KEY(user_id) REFERENCES user_account(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE trip (
 id BINARY(16) NOT NULL, owner_id BINARY(16) NOT NULL, title VARCHAR(200) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'DRAFT', current_version_id BINARY(16), deleted_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 PRIMARY KEY(id), KEY ix_trip_owner_updated(owner_id,updated_at), KEY ix_trip_owner_status(owner_id,status), CONSTRAINT ck_trip_dates CHECK(end_date>=start_date), CONSTRAINT ck_trip_status CHECK(status IN('DRAFT','ACTIVE','ARCHIVED','DELETED')), CONSTRAINT fk_trip_owner FOREIGN KEY(owner_id) REFERENCES user_account(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE city (
 id BINARY(16) NOT NULL, city_code VARCHAR(32) NOT NULL, name VARCHAR(128) NOT NULL, region_name VARCHAR(128), timezone VARCHAR(64) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 PRIMARY KEY(id), UNIQUE KEY uk_city_code(city_code), KEY ix_city_name_status(name,status), CONSTRAINT ck_city_status CHECK(status IN('ACTIVE','DISABLED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE trip_city (
 id BINARY(16) NOT NULL, trip_id BINARY(16) NOT NULL, city_id BINARY(16) NOT NULL, sequence_no INT NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 PRIMARY KEY(id), UNIQUE KEY uk_trip_city(trip_id,city_id), UNIQUE KEY uk_trip_city_seq(trip_id,sequence_no), KEY ix_trip_city_city(city_id), CONSTRAINT ck_trip_city_seq CHECK(sequence_no>=1), CONSTRAINT fk_trip_city_trip FOREIGN KEY(trip_id) REFERENCES trip(id), CONSTRAINT fk_trip_city_city FOREIGN KEY(city_id) REFERENCES city(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE trip_version (
 id BINARY(16) NOT NULL, trip_id BINARY(16) NOT NULL, parent_version_id BINARY(16), version_no INT NOT NULL, etag BINARY(32) NOT NULL, content_hash BINARY(32) NOT NULL, version_status VARCHAR(16) NOT NULL, schema_version VARCHAR(64) NOT NULL, model_version VARCHAR(128), prompt_version VARCHAR(128), created_by BINARY(16) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 PRIMARY KEY(id), UNIQUE KEY uk_trip_version_no(trip_id,version_no), UNIQUE KEY uk_trip_version_etag(etag), UNIQUE KEY uk_trip_version_hash(trip_id,content_hash), KEY ix_trip_version_status(trip_id,version_status), KEY ix_trip_version_parent(parent_version_id), CONSTRAINT ck_trip_version_no CHECK(version_no>=1), CONSTRAINT ck_trip_version_status CHECK(version_status IN('DRAFT','PUBLISHED','SUPERSEDED')), CONSTRAINT fk_trip_version_trip FOREIGN KEY(trip_id) REFERENCES trip(id), CONSTRAINT fk_trip_version_parent FOREIGN KEY(parent_version_id) REFERENCES trip_version(id), CONSTRAINT fk_trip_version_creator FOREIGN KEY(created_by) REFERENCES user_account(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
ALTER TABLE trip ADD CONSTRAINT fk_trip_current_version FOREIGN KEY(current_version_id) REFERENCES trip_version(id);

CREATE TABLE plan_snapshot (
 id BINARY(16) NOT NULL, trip_version_id BINARY(16) NOT NULL, plan_json JSON NOT NULL, summary_json JSON, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_plan_version(trip_version_id), CONSTRAINT fk_plan_version FOREIGN KEY(trip_version_id) REFERENCES trip_version(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE change_set (
 id BINARY(16) NOT NULL, trip_version_id BINARY(16) NOT NULL, base_version_id BINARY(16), change_no INT NOT NULL, change_type VARCHAR(32) NOT NULL, affected_paths_json JSON NOT NULL, change_json JSON NOT NULL, change_hash BINARY(32) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_change_no(trip_version_id,change_no), UNIQUE KEY uk_change_hash(trip_version_id,change_hash), KEY ix_change_base(base_version_id), CONSTRAINT ck_change_no CHECK(change_no>=1), CONSTRAINT ck_change_type CHECK(change_type IN('CREATE','UPDATE','DELETE','MOVE','REORDER','ROLLBACK')), CONSTRAINT fk_change_version FOREIGN KEY(trip_version_id) REFERENCES trip_version(id), CONSTRAINT fk_change_base FOREIGN KEY(base_version_id) REFERENCES trip_version(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE source_record (
 id BINARY(16) NOT NULL, source_type VARCHAR(32) NOT NULL, provider_name VARCHAR(64) NOT NULL, external_record_id VARCHAR(255) NOT NULL, sanitized_summary_json JSON, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_source_identity(source_type,provider_name,external_record_id), KEY ix_source_lookup(source_type,provider_name,external_record_id), CONSTRAINT ck_source_type CHECK(source_type IN('MAP','WEATHER','KNOWLEDGE_BASE','RESERVATION_RULE','POI','USER_INPUT','SYSTEM')), CONSTRAINT ck_source_status CHECK(status IN('ACTIVE','DISABLED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE source_snapshot (
 id BINARY(16) NOT NULL, source_record_id BINARY(16) NOT NULL, source_version VARCHAR(128), retrieved_at DATETIME(6) NOT NULL, valid_until DATETIME(6), freshness_status VARCHAR(16) NOT NULL, is_estimated BOOLEAN NOT NULL DEFAULT FALSE, content_hash BINARY(32) NOT NULL, sanitized_payload_json JSON, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_source_snapshot(source_record_id,content_hash,retrieved_at), KEY ix_source_freshness(source_record_id,freshness_status,valid_until), CONSTRAINT ck_source_freshness CHECK(freshness_status IN('FRESH','STALE','UNKNOWN')), CONSTRAINT ck_source_validity CHECK(valid_until IS NULL OR valid_until>=retrieved_at), CONSTRAINT fk_source_snapshot_record FOREIGN KEY(source_record_id) REFERENCES source_record(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE trip_version_source (
 trip_version_id BINARY(16) NOT NULL, source_snapshot_id BINARY(16) NOT NULL, field_path VARCHAR(255) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(trip_version_id,source_snapshot_id,field_path), KEY ix_version_source_snapshot(source_snapshot_id), CONSTRAINT fk_version_source_version FOREIGN KEY(trip_version_id) REFERENCES trip_version(id), CONSTRAINT fk_version_source_snapshot FOREIGN KEY(source_snapshot_id) REFERENCES source_snapshot(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE planning_task (
 id BINARY(16) NOT NULL, owner_id BINARY(16) NOT NULL, trip_id BINARY(16), base_version_id BINARY(16), task_type VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, idempotency_key VARCHAR(128) NOT NULL, request_hash BINARY(32) NOT NULL, quote_id BINARY(16), reserved_points BIGINT NOT NULL DEFAULT 0, request_json JSON NOT NULL, operation_deadline_at DATETIME(6) NOT NULL, confirmation_deadline_at DATETIME(6), state_version BIGINT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 PRIMARY KEY(id), UNIQUE KEY uk_task_idempotency (owner_id,idempotency_key), KEY ix_task_status_deadline(status,operation_deadline_at), KEY ix_task_owner_created(owner_id,created_at), CONSTRAINT ck_task_points CHECK(reserved_points>=0), CONSTRAINT ck_task_state CHECK(state_version>=0), CONSTRAINT ck_task_status CHECK(status IN('CREATED','BALANCE_RESERVED','QUEUED','PARSING','COLLECTING','SCHEDULING','ROUTING','ASSEMBLING','AWAITING_CONFIRMATION','SUCCEEDED','PARTIAL','FAILED','CANCELLED','REFUNDED')), CONSTRAINT fk_task_owner FOREIGN KEY(owner_id) REFERENCES user_account(id), CONSTRAINT fk_task_trip FOREIGN KEY(trip_id) REFERENCES trip(id), CONSTRAINT fk_task_version FOREIGN KEY(base_version_id) REFERENCES trip_version(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE task_step (
 id BINARY(16) NOT NULL, task_id BINARY(16) NOT NULL, step_name VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, attempt_no INT NOT NULL DEFAULT 1, lease_owner VARCHAR(128), lease_expires_at DATETIME(6), heartbeat_at DATETIME(6), input_hash BINARY(32) NOT NULL, output_result_id BINARY(16), started_at DATETIME(6), finished_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_step_attempt(task_id,step_name,attempt_no), KEY ix_step_lease(status,lease_expires_at), KEY ix_step_task_status(task_id,status), CONSTRAINT ck_step_attempt CHECK(attempt_no>=1), CONSTRAINT ck_step_times CHECK(finished_at IS NULL OR started_at IS NULL OR finished_at>=started_at), CONSTRAINT ck_step_status CHECK(status IN('PENDING','RUNNING','SUCCEEDED','PARTIAL','DEGRADED','FAILED','CANCELLED')), CONSTRAINT fk_step_task FOREIGN KEY(task_id) REFERENCES planning_task(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE task_event (
 id BINARY(16) NOT NULL, task_id BINARY(16) NOT NULL, sequence_no BIGINT NOT NULL, event_type VARCHAR(64) NOT NULL, event_json JSON NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_task_event_sequence(task_id,sequence_no), KEY ix_task_event_created(task_id,created_at), CONSTRAINT ck_task_event_sequence CHECK(sequence_no>=1), CONSTRAINT fk_task_event_task FOREIGN KEY(task_id) REFERENCES planning_task(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE outbox_event (
 id BINARY(16) NOT NULL, aggregate_type VARCHAR(32) NOT NULL, aggregate_id BINARY(16) NOT NULL, event_type VARCHAR(64) NOT NULL, idempotency_key VARCHAR(128) NOT NULL, payload_json JSON NOT NULL, publish_status VARCHAR(16) NOT NULL DEFAULT 'PENDING', attempt_count INT NOT NULL DEFAULT 0, available_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), published_at DATETIME(6), dead_at DATETIME(6), last_error VARCHAR(1000), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_outbox_idempotency(aggregate_type,aggregate_id,idempotency_key), KEY ix_outbox_pending(publish_status,available_at), KEY ix_outbox_aggregate(aggregate_type,aggregate_id), CONSTRAINT ck_outbox_type CHECK(aggregate_type IN('TASK','POINTS','TRIP_VERSION')), CONSTRAINT ck_outbox_status CHECK(publish_status IN('PENDING','PUBLISHED','DEAD')), CONSTRAINT ck_outbox_attempt CHECK(attempt_count>=0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE agent_result (
 id BINARY(16) NOT NULL, task_id BINARY(16) NOT NULL, step_id BINARY(16) NOT NULL, attempt_no INT NOT NULL, agent_id VARCHAR(64) NOT NULL, schema_version VARCHAR(64) NOT NULL, request_id VARCHAR(128) NOT NULL, idempotency_key VARCHAR(128) NOT NULL, request_hash BINARY(32) NOT NULL, trace_id VARCHAR(128) NOT NULL, status VARCHAR(16) NOT NULL, result_json JSON, message VARCHAR(1000), error_code VARCHAR(64), degraded_fields_json JSON, generated_at DATETIME(6) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_agent_request(request_id), UNIQUE KEY uk_agent_attempt(task_id,step_id,attempt_no), UNIQUE KEY uk_agent_idempotency(task_id,step_id,idempotency_key), KEY ix_agent_status(task_id,step_id,status), KEY ix_agent_trace(trace_id), CONSTRAINT ck_agent_attempt CHECK(attempt_no>=1), CONSTRAINT ck_agent_status CHECK(status IN('ok','partial','degraded','failed')), CONSTRAINT fk_agent_task FOREIGN KEY(task_id) REFERENCES planning_task(id), CONSTRAINT fk_agent_step FOREIGN KEY(step_id) REFERENCES task_step(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
ALTER TABLE task_step ADD CONSTRAINT fk_step_output_result FOREIGN KEY(output_result_id) REFERENCES agent_result(id);
CREATE TABLE agent_result_source (
 result_id BINARY(16) NOT NULL, source_snapshot_id BINARY(16) NOT NULL, PRIMARY KEY(result_id,source_snapshot_id), CONSTRAINT fk_result_source_result FOREIGN KEY(result_id) REFERENCES agent_result(id), CONSTRAINT fk_result_source_snapshot FOREIGN KEY(source_snapshot_id) REFERENCES source_snapshot(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE poi (
 id BINARY(16) NOT NULL, city_id BINARY(16) NOT NULL, external_poi_id VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL, category VARCHAR(64), status VARCHAR(16) NOT NULL DEFAULT 'DRAFT', current_snapshot_id BINARY(16), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_poi_external(city_id,external_poi_id), KEY ix_poi_name(city_id,name), KEY ix_poi_status(city_id,status), CONSTRAINT ck_poi_status CHECK(status IN('DRAFT','PUBLISHED','DISABLED')), CONSTRAINT fk_poi_city FOREIGN KEY(city_id) REFERENCES city(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE poi_snapshot (
 id BINARY(16) NOT NULL, poi_id BINARY(16) NOT NULL, source_snapshot_id BINARY(16) NOT NULL, snapshot_no INT NOT NULL, name VARCHAR(255) NOT NULL, latitude DECIMAL(10,7), longitude DECIMAL(10,7), coordinate_system VARCHAR(16), category VARCHAR(64), payload_json JSON, content_hash BINARY(32) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_poi_snapshot_no(poi_id,snapshot_no), UNIQUE KEY uk_poi_snapshot_hash(poi_id,content_hash), KEY ix_poi_snapshot_source(source_snapshot_id), CONSTRAINT ck_poi_snapshot_no CHECK(snapshot_no>=1), CONSTRAINT ck_poi_coordinates CHECK((latitude IS NULL AND longitude IS NULL) OR(latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180)), CONSTRAINT ck_poi_coordinate_system CHECK(coordinate_system IS NULL OR coordinate_system IN('WGS84','GCJ02')), CONSTRAINT fk_poi_snapshot_poi FOREIGN KEY(poi_id) REFERENCES poi(id), CONSTRAINT fk_poi_snapshot_source FOREIGN KEY(source_snapshot_id) REFERENCES source_snapshot(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
ALTER TABLE poi ADD CONSTRAINT fk_poi_current_snapshot FOREIGN KEY(current_snapshot_id) REFERENCES poi_snapshot(id);
CREATE TABLE poi_alias (
 id BINARY(16) NOT NULL, poi_id BINARY(16) NOT NULL, alias VARCHAR(255) NOT NULL, alias_type VARCHAR(32) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', deleted_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_poi_alias(poi_id,alias), KEY ix_poi_alias(alias), KEY ix_poi_alias_status(poi_id,status), CONSTRAINT ck_poi_alias_status CHECK(status IN('ACTIVE','DISABLED')), CONSTRAINT fk_poi_alias_poi FOREIGN KEY(poi_id) REFERENCES poi(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE knowledge_entry (
 id BINARY(16) NOT NULL, entry_key VARCHAR(128) NOT NULL, poi_id BINARY(16), city_id BINARY(16) NOT NULL, parent_entry_id BINARY(16), version_no INT NOT NULL, title VARCHAR(255) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'DRAFT', effective_from DATETIME(6), effective_until DATETIME(6), last_verified_at DATETIME(6), content_hash BINARY(32) NOT NULL, source_snapshot_id BINARY(16) NOT NULL, created_by BINARY(16) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_knowledge_version(entry_key,version_no), UNIQUE KEY uk_knowledge_hash(entry_key,content_hash), KEY ix_knowledge_publish(city_id,status,effective_until), KEY ix_knowledge_poi(poi_id,status), CONSTRAINT ck_knowledge_version CHECK(version_no>=1), CONSTRAINT ck_knowledge_status CHECK(status IN('DRAFT','REVIEW','PUBLISHED','DISABLED')), CONSTRAINT ck_knowledge_validity CHECK(effective_until IS NULL OR effective_from IS NULL OR effective_until>=effective_from), CONSTRAINT fk_knowledge_poi FOREIGN KEY(poi_id) REFERENCES poi(id), CONSTRAINT fk_knowledge_city FOREIGN KEY(city_id) REFERENCES city(id), CONSTRAINT fk_knowledge_parent FOREIGN KEY(parent_entry_id) REFERENCES knowledge_entry(id), CONSTRAINT fk_knowledge_source FOREIGN KEY(source_snapshot_id) REFERENCES source_snapshot(id), CONSTRAINT fk_knowledge_creator FOREIGN KEY(created_by) REFERENCES user_account(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE knowledge_chunk (
 id BINARY(16) NOT NULL, knowledge_entry_id BINARY(16) NOT NULL, chunk_no INT NOT NULL, content_text TEXT NOT NULL, content_hash BINARY(32) NOT NULL, vector_record_id VARCHAR(255), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_chunk_no(knowledge_entry_id,chunk_no), UNIQUE KEY uk_chunk_hash(knowledge_entry_id,content_hash), KEY ix_chunk_vector(vector_record_id), CONSTRAINT ck_chunk_no CHECK(chunk_no>=1), CONSTRAINT fk_chunk_entry FOREIGN KEY(knowledge_entry_id) REFERENCES knowledge_entry(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE reservation_rule (
 id BINARY(16) NOT NULL, rule_key VARCHAR(128) NOT NULL, poi_id BINARY(16) NOT NULL, parent_rule_id BINARY(16), version_no INT NOT NULL, ticket_type VARCHAR(128) NOT NULL, audience VARCHAR(128), channel VARCHAR(128), release_timezone VARCHAR(64) NOT NULL, currency CHAR(3), amount_minor BIGINT UNSIGNED, effective_from DATETIME(6) NOT NULL, effective_until DATETIME(6), last_verified_at DATETIME(6) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'DRAFT', source_snapshot_id BINARY(16) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_rule_version(rule_key,version_no), KEY ix_rule_validity(poi_id,status,effective_from,effective_until), CONSTRAINT ck_rule_version CHECK(version_no>=1), CONSTRAINT ck_rule_status CHECK(status IN('DRAFT','REVIEW','PUBLISHED','DISABLED')), CONSTRAINT ck_rule_amount CHECK((currency IS NULL AND amount_minor IS NULL) OR(currency IS NOT NULL AND amount_minor IS NOT NULL)), CONSTRAINT ck_rule_validity CHECK(effective_until IS NULL OR effective_until>=effective_from), CONSTRAINT fk_rule_poi FOREIGN KEY(poi_id) REFERENCES poi(id), CONSTRAINT fk_rule_parent FOREIGN KEY(parent_rule_id) REFERENCES reservation_rule(id), CONSTRAINT fk_rule_source FOREIGN KEY(source_snapshot_id) REFERENCES source_snapshot(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE points_account (
 id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, balance_points BIGINT NOT NULL DEFAULT 0, state_version BIGINT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_points_account_user(user_id), KEY ix_points_account_user(user_id), CONSTRAINT ck_points_balance CHECK(balance_points>=0), CONSTRAINT ck_points_account_version CHECK(state_version>=0), CONSTRAINT fk_points_account_user FOREIGN KEY(user_id) REFERENCES user_account(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE points_quote (
 id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, task_id BINARY(16), quote_reference VARCHAR(128) NOT NULL, quote_version INT NOT NULL DEFAULT 1, plan_count TINYINT UNSIGNED NOT NULL, points BIGINT UNSIGNED NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ISSUED', expires_at DATETIME(6) NOT NULL, accepted_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_quote_reference(quote_reference), UNIQUE KEY uk_quote_task(task_id), KEY ix_quote_user_status(user_id,status,expires_at), CONSTRAINT ck_quote_version CHECK(quote_version>=1), CONSTRAINT ck_quote_count CHECK(plan_count BETWEEN 1 AND 3), CONSTRAINT ck_quote_points CHECK(points>0), CONSTRAINT ck_quote_expiry CHECK(expires_at>created_at), CONSTRAINT ck_quote_status CHECK(status IN('ISSUED','ACCEPTED','EXPIRED','CANCELLED','CONSUMED')), CONSTRAINT fk_quote_user FOREIGN KEY(user_id) REFERENCES user_account(id), CONSTRAINT fk_quote_task FOREIGN KEY(task_id) REFERENCES planning_task(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
ALTER TABLE planning_task ADD CONSTRAINT fk_task_quote FOREIGN KEY(quote_id) REFERENCES points_quote(id);
CREATE TABLE points_ledger (
 id BINARY(16) NOT NULL, account_id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, task_id BINARY(16), quote_id BINARY(16), entry_type VARCHAR(16) NOT NULL, points_delta BIGINT NOT NULL, balance_before BIGINT NOT NULL, balance_after BIGINT NOT NULL, business_reference VARCHAR(128) NOT NULL, metadata_json JSON, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_ledger_reference(business_reference), KEY ix_ledger_account(account_id,created_at), KEY ix_ledger_task(task_id,created_at), KEY ix_ledger_user(user_id,created_at), CONSTRAINT ck_ledger_type CHECK(entry_type IN('GRANT','RESERVE','CONFIRM','REFUND','TOP_UP','ADMIN_ADJUST')), CONSTRAINT ck_ledger_delta CHECK((entry_type='CONFIRM' AND points_delta=0) OR(entry_type<>'CONFIRM' AND points_delta<>0)), CONSTRAINT ck_ledger_direction CHECK((entry_type IN('GRANT','REFUND','TOP_UP') AND points_delta>0) OR(entry_type='RESERVE' AND points_delta<0) OR(entry_type='CONFIRM' AND points_delta=0) OR(entry_type='ADMIN_ADJUST' AND points_delta<>0)), CONSTRAINT ck_ledger_before CHECK(balance_before>=0), CONSTRAINT ck_ledger_after CHECK(balance_after>=0), CONSTRAINT ck_ledger_balance CHECK(balance_after=balance_before+points_delta), CONSTRAINT fk_ledger_account FOREIGN KEY(account_id) REFERENCES points_account(id), CONSTRAINT fk_ledger_user FOREIGN KEY(user_id) REFERENCES user_account(id), CONSTRAINT fk_ledger_task FOREIGN KEY(task_id) REFERENCES planning_task(id), CONSTRAINT fk_ledger_quote FOREIGN KEY(quote_id) REFERENCES points_quote(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE post (
 id BINARY(16) NOT NULL, owner_id BINARY(16) NOT NULL, source_version_id BINARY(16), visibility VARCHAR(16) NOT NULL DEFAULT 'PRIVATE', moderation_status VARCHAR(16) NOT NULL DEFAULT 'DRAFT', title VARCHAR(200) NOT NULL, content_json JSON NOT NULL, sanitized_content_json JSON, published_at DATETIME(6), withdrawn_at DATETIME(6), deleted_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), KEY ix_post_public(visibility,moderation_status,published_at), KEY ix_post_owner(owner_id,updated_at), CONSTRAINT ck_post_visibility CHECK(visibility IN('PRIVATE','PUBLIC')), CONSTRAINT ck_post_moderation CHECK(moderation_status IN('DRAFT','PENDING','PUBLISHED','WITHDRAWN','REJECTED')), CONSTRAINT fk_post_owner FOREIGN KEY(owner_id) REFERENCES user_account(id), CONSTRAINT fk_post_version FOREIGN KEY(source_version_id) REFERENCES trip_version(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE post_comment (
 id BINARY(16) NOT NULL, post_id BINARY(16) NOT NULL, author_id BINARY(16) NOT NULL, parent_comment_id BINARY(16), body_text TEXT NOT NULL, moderation_status VARCHAR(16) NOT NULL DEFAULT 'VISIBLE', deleted_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), KEY ix_comment_post(post_id,created_at), KEY ix_comment_parent(parent_comment_id,created_at), CONSTRAINT ck_comment_status CHECK(moderation_status IN('VISIBLE','HIDDEN','REPORTED','DELETED')), CONSTRAINT fk_comment_post FOREIGN KEY(post_id) REFERENCES post(id), CONSTRAINT fk_comment_author FOREIGN KEY(author_id) REFERENCES user_account(id), CONSTRAINT fk_comment_parent FOREIGN KEY(parent_comment_id) REFERENCES post_comment(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE interaction (
 id BINARY(16) NOT NULL, post_id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, interaction_type VARCHAR(16) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', removed_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_interaction(post_id,user_id,interaction_type), KEY ix_interaction_post_type_status(post_id,interaction_type,status), CONSTRAINT ck_interaction_type CHECK(interaction_type IN('LIKE','FAVORITE','REUSE')), CONSTRAINT ck_interaction_status CHECK(status IN('ACTIVE','REMOVED')), CONSTRAINT fk_interaction_post FOREIGN KEY(post_id) REFERENCES post(id), CONSTRAINT fk_interaction_user FOREIGN KEY(user_id) REFERENCES user_account(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE moderation_case (
 id BINARY(16) NOT NULL, target_type VARCHAR(16) NOT NULL, target_id BINARY(16) NOT NULL, case_no INT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'OPEN', opened_by BINARY(16) NOT NULL, assigned_to BINARY(16), resolution_code VARCHAR(64), resolution_note VARCHAR(1000), opened_at DATETIME(6) NOT NULL, resolved_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_moderation_target(target_type,target_id,case_no), KEY ix_moderation_status(status,assigned_to,created_at), CONSTRAINT ck_moderation_target CHECK(target_type IN('POST','COMMENT')), CONSTRAINT ck_moderation_no CHECK(case_no>=1), CONSTRAINT ck_moderation_status CHECK(status IN('OPEN','REVIEWING','RESOLVED','REJECTED')), CONSTRAINT fk_moderation_opener FOREIGN KEY(opened_by) REFERENCES user_account(id), CONSTRAINT fk_moderation_assignee FOREIGN KEY(assigned_to) REFERENCES user_account(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE report (
 id BINARY(16) NOT NULL, target_type VARCHAR(16) NOT NULL, target_id BINARY(16) NOT NULL, reporter_id BINARY(16) NOT NULL, reason_code VARCHAR(64) NOT NULL, detail_text VARCHAR(1000), moderation_case_id BINARY(16), status VARCHAR(16) NOT NULL DEFAULT 'OPEN', created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_report_target(reporter_id,target_type,target_id), KEY ix_report_target(target_type,target_id,status), KEY ix_report_case(moderation_case_id,status), CONSTRAINT ck_report_target CHECK(target_type IN('POST','COMMENT')), CONSTRAINT ck_report_status CHECK(status IN('OPEN','ACCEPTED','REJECTED','WITHDRAWN')), CONSTRAINT fk_report_reporter FOREIGN KEY(reporter_id) REFERENCES user_account(id), CONSTRAINT fk_report_case FOREIGN KEY(moderation_case_id) REFERENCES moderation_case(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE ranking_entry (
 id BINARY(16) NOT NULL, ranking_scope VARCHAR(64) NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, post_id BINARY(16) NOT NULL, rank_no INT NOT NULL, score DECIMAL(12,6) NOT NULL, formula_version VARCHAR(64) NOT NULL, visible BOOLEAN NOT NULL DEFAULT TRUE, computed_at DATETIME(6) NOT NULL, PRIMARY KEY(id), UNIQUE KEY uk_ranking_identity(ranking_scope,period_start,post_id,formula_version), KEY ix_ranking_scope(ranking_scope,period_start,period_end,rank_no), KEY ix_ranking_post(post_id,visible), CONSTRAINT ck_ranking_period CHECK(period_end>=period_start), CONSTRAINT ck_ranking_no CHECK(rank_no>=1), CONSTRAINT ck_ranking_score CHECK(score>=0), CONSTRAINT fk_ranking_post FOREIGN KEY(post_id) REFERENCES post(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE user_preference (
 id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, preference_key VARCHAR(64) NOT NULL, version_no INT NOT NULL, value_json JSON NOT NULL, source_type VARCHAR(32) NOT NULL, confidence DECIMAL(5,4), weight INT NOT NULL DEFAULT 0, last_used_at DATETIME(6), status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE', cleared_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_preference_version(user_id,preference_key,version_no), KEY ix_preference_active(user_id,status,weight), CONSTRAINT ck_preference_version CHECK(version_no>=1), CONSTRAINT ck_preference_source CHECK(source_type IN('EXPLICIT','HISTORY_ANALYSIS','SYSTEM')), CONSTRAINT ck_preference_confidence CHECK(confidence IS NULL OR(confidence>=0 AND confidence<=1)), CONSTRAINT ck_preference_status CHECK(status IN('ACTIVE','CLEARED')), CONSTRAINT fk_preference_user FOREIGN KEY(user_id) REFERENCES user_account(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE preference_evidence (
 id BINARY(16) NOT NULL, preference_id BINARY(16) NOT NULL, source_type VARCHAR(32) NOT NULL, source_ref_id BINARY(16), evidence_hash BINARY(32) NOT NULL, observed_at DATETIME(6) NOT NULL, weight_delta INT NOT NULL DEFAULT 0, evidence_json JSON, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_preference_evidence(preference_id,evidence_hash), KEY ix_preference_evidence(preference_id,observed_at), CONSTRAINT fk_preference_evidence_preference FOREIGN KEY(preference_id) REFERENCES user_preference(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE preference_summary (
 id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, summary_version INT NOT NULL, sample_count INT NOT NULL, eligible BOOLEAN NOT NULL DEFAULT FALSE, summary_json JSON NOT NULL, generated_at DATETIME(6) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_summary_version(user_id,summary_version), KEY ix_summary_generated(user_id,generated_at), CONSTRAINT ck_summary_version CHECK(summary_version>=1), CONSTRAINT ck_summary_sample CHECK(sample_count>=0), CONSTRAINT ck_summary_eligible CHECK(eligible=FALSE OR sample_count>=3), CONSTRAINT fk_summary_user FOREIGN KEY(user_id) REFERENCES user_account(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE object_metadata (
 id BINARY(16) NOT NULL, owner_id BINARY(16) NOT NULL, object_key VARCHAR(255) NOT NULL, storage_backend VARCHAR(16) NOT NULL, mime_type VARCHAR(128) NOT NULL, size_bytes BIGINT UNSIGNED NOT NULL, sha256 BINARY(32) NOT NULL, license_type VARCHAR(64), source_uri VARCHAR(2048), status VARCHAR(16) NOT NULL DEFAULT 'PENDING', expires_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_object_key(object_key), UNIQUE KEY uk_object_sha256(sha256), KEY ix_object_cleanup(owner_id,status,expires_at), CONSTRAINT ck_object_backend CHECK(storage_backend IN('LOCAL','MINIO')), CONSTRAINT ck_object_status CHECK(status IN('PENDING','AVAILABLE','EXPIRED','DELETED')), CONSTRAINT fk_object_owner FOREIGN KEY(owner_id) REFERENCES user_account(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE export_job (
 id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, trip_version_id BINARY(16) NOT NULL, object_metadata_id BINARY(16), export_format VARCHAR(16) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'PENDING', download_token_hash BINARY(32), expires_at DATETIME(6), completed_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_export_token(download_token_hash), KEY ix_export_user_created(user_id,created_at), KEY ix_export_cleanup(status,expires_at), CONSTRAINT ck_export_format CHECK(export_format IN('PDF','ICS')), CONSTRAINT ck_export_status CHECK(status IN('PENDING','RUNNING','SUCCEEDED','FAILED','EXPIRED')), CONSTRAINT fk_export_user FOREIGN KEY(user_id) REFERENCES user_account(id), CONSTRAINT fk_export_version FOREIGN KEY(trip_version_id) REFERENCES trip_version(id), CONSTRAINT fk_export_object FOREIGN KEY(object_metadata_id) REFERENCES object_metadata(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE reminder_candidate (
 id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, trip_id BINARY(16) NOT NULL, source_type VARCHAR(32) NOT NULL, reservation_rule_id BINARY(16), source_snapshot_id BINARY(16), candidate_type VARCHAR(64) NOT NULL, occurs_at DATETIME(6) NOT NULL, timezone VARCHAR(64) NOT NULL, dedupe_key VARCHAR(255) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'CANDIDATE', payload_json JSON NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_reminder_dedupe(user_id,dedupe_key), KEY ix_reminder_user_status(user_id,status,occurs_at), KEY ix_reminder_status(status,occurs_at), CONSTRAINT ck_reminder_source CHECK((source_type='RESERVATION_RULE' AND reservation_rule_id IS NOT NULL AND source_snapshot_id IS NULL) OR(source_type='WEATHER' AND reservation_rule_id IS NULL AND source_snapshot_id IS NOT NULL)), CONSTRAINT ck_reminder_status CHECK(status IN('CANDIDATE','CONFIRMED','CANCELLED','EXPIRED')), CONSTRAINT fk_reminder_user FOREIGN KEY(user_id) REFERENCES user_account(id), CONSTRAINT fk_reminder_trip FOREIGN KEY(trip_id) REFERENCES trip(id), CONSTRAINT fk_reminder_rule FOREIGN KEY(reservation_rule_id) REFERENCES reservation_rule(id), CONSTRAINT fk_reminder_source FOREIGN KEY(source_snapshot_id) REFERENCES source_snapshot(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE notification (
 id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, reminder_candidate_id BINARY(16), notification_type VARCHAR(32) NOT NULL, dedupe_key VARCHAR(255) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'PENDING', scheduled_at DATETIME(6) NOT NULL, delivered_at DATETIME(6), cancelled_at DATETIME(6), expires_at DATETIME(6), payload_json JSON NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_notification_dedupe(user_id,notification_type,dedupe_key), KEY ix_notification_delivery(status,scheduled_at), KEY ix_notification_user(user_id,status), CONSTRAINT ck_notification_status CHECK(status IN('PENDING','DELIVERED','CANCELLED','EXPIRED')), CONSTRAINT fk_notification_user FOREIGN KEY(user_id) REFERENCES user_account(id), CONSTRAINT fk_notification_candidate FOREIGN KEY(reminder_candidate_id) REFERENCES reminder_candidate(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE audit_event (
 id BINARY(16) NOT NULL, actor_user_id BINARY(16), action VARCHAR(64) NOT NULL, resource_type VARCHAR(64) NOT NULL, resource_id BINARY(16), request_id VARCHAR(128), trace_id VARCHAR(128), outcome VARCHAR(16) NOT NULL, error_code VARCHAR(64), metadata_json JSON, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), KEY ix_audit_resource(resource_type,resource_id,created_at), KEY ix_audit_actor(actor_user_id,created_at), KEY ix_audit_request(request_id), CONSTRAINT ck_audit_outcome CHECK(outcome IN('SUCCESS','DENIED','FAILURE')), CONSTRAINT fk_audit_actor FOREIGN KEY(actor_user_id) REFERENCES user_account(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
